<?php
namespace App\Services\Catalog;use App\Models\ProductVariant;use Illuminate\Support\Facades\DB;
class PricingService{public function price(ProductVariant $variant):int{$sale=DB::table('sale_campaign_items as i')->join('sale_campaigns as c','c.id','=','i.campaign_id')->where('i.variant_id',$variant->id)->where('c.is_active',true)->where('c.starts_at','<=',now())->where('c.ends_at','>=',now())->where(fn($q)=>$q->whereNull('i.stock_limit')->orWhereColumn('i.sold','<','i.stock_limit'))->min('i.sale_price');return (int)($sale??$variant->price);}public function activeItem(int $variantId){return DB::table('sale_campaign_items as i')->join('sale_campaigns as c','c.id','=','i.campaign_id')->where('i.variant_id',$variantId)->where('c.is_active',true)->where('c.starts_at','<=',now())->where('c.ends_at','>=',now())->where(fn($q)=>$q->whereNull('i.stock_limit')->orWhereColumn('i.sold','<','i.stock_limit'))->orderBy('i.sale_price')->select('i.*')->first();}}
